// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.assume(amount <= 1 ether);

        uint256 initSenderBal = c.getBalance(actor);
        uint256 initTotalBal = sumAllBalances(actor);
        uint256 initEth = address(c).balance;

        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();

        uint256 finalSenderBal = c.getBalance(actor);
        uint256 finalTotalBal = sumAllBalances(actor);
        uint256 finalEth = address(c).balance;

        assertTrue(finalSenderBal == initSenderBal + amount && finalTotalBal == initTotalBal + amount && finalEth == initEth + amount);
    }

    function sumAllBalances(address actor) internal view returns (uint256 total) {
        total = c.getBalance(actor) + c.getBalance(address(0));
    }
}
